const item = $('Edit Fields5').first().json;
const output = item.output;

// normaliza asteriscos duplicados
function limparTexto(texto) {
  return String(texto || "")
    .replace(/\*+\*/g, "*")
    .trim();
}

// quebra texto grande em blocos por linha em branco
function quebrarTexto(texto) {
  return limparTexto(texto)
    .split("\n\n")
    .map(t => t.trim())
    .filter(t => t !== "");
}

// CASO 1: veio como objeto com campo mensagens (array) — formato atual dos especialistas
if (output && typeof output === "object" && Array.isArray(output.mensagens)) {
  return output.mensagens
    .map((msg, index) => {
      const texto = limparTexto(msg?.texto);
      if (!texto) return null;
      return {
        json: {
          numero: msg?.numero || index + 1,
          texto
        }
      };
    })
    .filter(Boolean);
}

// CASO 2: já veio como array de mensagens (formato legado, ex.: VITA RESPONDE)
if (Array.isArray(output)) {
  return output
    .map((msg, index) => {
      const texto = limparTexto(msg?.texto || msg);
      if (!texto) return null;
      return {
        json: {
          numero: msg?.numero || index + 1,
          texto
        }
      };
    })
    .filter(Boolean);
}

// CASO 3: veio como string direta
if (typeof output === "string") {
  return quebrarTexto(output).map((parte, index) => ({
    json: {
      numero: index + 1,
      texto: parte
    }
  }));
}

// CASO 4: veio como objeto com campo texto
if (output && typeof output === "object" && typeof output.texto === "string") {
  return quebrarTexto(output.texto).map((parte, index) => ({
    json: {
      numero: index + 1,
      texto: parte
    }
  }));
}

// CASO 5: fallback
return [
  {
    json: {
      numero: 1,
      texto: ""
    }
  }
];

const binaries = $input.first().binary || {};

return Object.entries(binaries).map(([key, file], index) => {
  return {
    json: {
      page_number: index + 1,
      file_name: file.fileName || key,
      mime_type: file.mimeType,
    },
    binary: {
      data: file,
    },
  };
});

const c = $('CONFIG_LAB').first().json.lab_config.agenda;
const entrada = $('Entende_Contexto').first().json.output.consulta_agenda;
const local = String(entrada.local || '');
const dias = c.dias_permitidos || [];
const falha = motivo => [{json:{ok:false,status_execucao:'erro',error:motivo,motivo,datas:[],local}}];
if (!dias.length || !(c.locais || []).includes(local) || !c.hora_inicio || !c.hora_fim || !(c.duracao_minutos > 0)) return falha('Agenda do Lab não configurada para este local.');
const feriados = new Set($('pegaFeriado').all().map(i=>i.json.start?.date || i.json.start?.dateTime?.slice(0,10)).filter(Boolean));
const soma = (s,n) => {const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const valida = s => !feriados.has(s) && dias.includes(new Date(s+'T12:00:00Z').getUTCDay());
const dataBR = String($('payload_webhook').first().json.data);
const hoje = dataBR.includes('/')?dataBR.split('/').reverse().join('-'):dataBR.slice(0,10);
let datas = Array.isArray(entrada.datas_especificas)?[...entrada.datas_especificas]:[];
if (datas.some(s=>!/^\d{4}-\d{2}-\d{2}$/.test(s)||Number.isNaN(Date.parse(s+'T12:00:00Z')))) return falha('Data inválida na consulta.');
const busca_automatica = datas.length === 0;
if(busca_automatica)for(let i=0;i<60&&datas.length<15;i++){const s=soma(hoje,i);if(valida(s))datas.push(s);}
const proximas=(s,direcao)=>{for(let i=1;i<=30;i++){const x=soma(s,i*direcao);if(x>=hoje&&valida(x))return x;}return null;};
const finais=new Set(),alteracoes=[];
for(const s of datas){if(s<hoje)continue;if(valida(s)){finais.add(s);continue;}const ant=proximas(s,-1),pos=proximas(s,1);if(ant)finais.add(ant);if(pos)finais.add(pos);alteracoes.push({data_original:s,local,motivo:feriados.has(s)?'feriado':'dia_sem_atendimento_no_local',data_valida_anterior:ant,proxima_data_valida:pos});}
return [{json:{ok:true,local,datas:[...finais].sort(),alteracoes_datas:alteracoes,busca_automatica}}];

