      userEnteredValue: {
        boolValue: valor
      }
    };
  }

  if (typeof valor === 'number') {
    return {
      userEnteredValue: {
        numberValue: valor
      }
    };
  }

  if (Array.isArray(valor)) {
    return {
      userEnteredValue: {
        stringValue: JSON.stringify(valor)
      }
    };
