const c=$('CONFIG_LAB').first().json.lab_config.agenda;
const item=$input.first();
const output={...(item.json.output||{})};
const a=output.acao,d=output.dados_agendamento||{};
let motivo='';
if(a==='autorizar_criacao'||a==='autorizar_atualizacao'){
 if(!(c.duracao_minutos>0)||!c.hora_inicio||!c.hora_fim||!(c.locais||[]).includes(d.local)||!(c.dias_permitidos||[]).length)motivo='A configuração de agenda do Lab está incompleta.';
 else if(!d.nome_completo||!d.servico||!d.data||!d.horario)motivo='Faltam dados para confirmar o compromisso.';
 else {
  const inicio=DateTime.fromISO(d.data+'T'+d.horario,{zone:c.fuso});
  const fim=inicio.plus({minutes:Number(c.duracao_minutos)+Number(c.intervalo_minutos||0)});
  let disponibilidade={};try{disponibilidade=$('aplica_regras_agenda').first().json;}catch{}
  const intervalos=(disponibilidade.data||[]).filter(x=>x.periodo_consultado?.data_inicio===d.data).flatMap(x=>x.horarios_livres||[]).filter(x=>x&&typeof x==='object');
  const cabe=intervalos.some(x=>inicio>=DateTime.fromISO(d.data+'T'+x.inicio,{zone:c.fuso})&&fim<=DateTime.fromISO(d.data+'T'+x.fim,{zone:c.fuso}));
  if(!inicio.isValid||disponibilidade.status_execucao!=='sucesso'||!cabe)motivo='É necessário consultar e confirmar um horário disponível antes de efetivar a operação.';
 }
}
if((a==='autorizar_atualizacao'||a==='autorizar_cancelamento')){
 const registros=$('payload_bd').first().json.agendamentos||[];
 if(!d.calendar_event_id||!registros.some(x=>x.calendar_event_id===d.calendar_event_id))motivo='É necessário identificar um compromisso deste contato antes de alterar ou cancelar.';
}
if(motivo){output.acao='coletar_dados';output.informacoes=[motivo];output.pergunta='';output.resumo=motivo;}
return [{...item,json:{...item.json,output}}];
